            self.assertEqual(ast.dump(policy[name].args),ast.dump(after['_reference_'+name.lstrip('_')].args))
            self.assertEqual([ast.dump(n) for n in policy[name].body],[ast.dump(n) for n in after['_reference_'+name.lstrip('_')].body])

